(function(){
const area=document.querySelector('#admin-panel');if(!area)return;area.insertAdjacentHTML('beforeend','<section id="admin-orders" class="admin-orders" hidden><h2>Pedidos recebidos</h2><div id="admin-order-list"></div></section>');
async function loadOrders(){const list=document.querySelector('#admin-order-list');if(!list)return;try{const rows=await request('/rest/v1/orders?select=id,public_number,status,payment_method,fulfillment_method,delivery_address,amount_due_cents,cashback_reserved_cents,created_at,order_items(product_name,variant_name,quantity,line_total_cents)&order=created_at.desc');list.innerHTML=rows.length?rows.map(o=>`<article class="order-card"><strong>Pedido #${o.public_number}</strong><span>${o.status}</span><small>${new Date(o.created_at).toLocaleString('pt-BR')} · ${o.payment_method} · ${o.fulfillment_method}</small><p>${o.order_items.map(i=>`${i.quantity}× ${i.product_name} (${i.variant_name}) — ${money(i.line_total_cents)}`).join('<br>')}</p><b>Total: ${money(o.amount_due_cents)}</b>${o.status==='pending'?`<div class="admin-order-actions"><button class="primary" data-confirm="${o.id}">Confirmar venda</button><button class="secondary" data-cancel="${o.id}">Cancelar</button></div>`:''}</article>`).join(''):'<p>Nenhum pedido recebido.</p>'}catch(e){list.innerHTML='<p>'+e.message+'</p>'}}
window.loadAdminOrders=loadOrders;document.querySelector('#admin-order-list').onclick=async e=>{const b=e.target.closest('[data-confirm],[data-cancel]');if(!b)return;const status=b.dataset.confirm?'confirmed':'cancelled';try{await request('/rest/v1/rpc/admin_set_order_status_v2',{method:'POST',body:JSON.stringify({p_order_id:b.dataset.confirm||b.dataset.cancel,p_status:status})});loadOrders()}catch(x){alert(x.message)}};
})();


